{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공원 풋살장 이용 시 조례 별표의 어린이 무료 기준이 전원이 어린이일 때만 적용되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 도시공원 조례 별표 2의 풋살장 비고는 ‘어린이는 무료(이 경우 청소년 및 어린이의 팀 구성원 비율이 50% 이상일 때 적용)’라고 정하고 있다. 따라서 어린이 무료 기준은 전원이 어린이일 때만 적용되는 것이 아니라, 팀 구성원 중 청소년 및 어린이의 비율이 50% 이상이면 적용된다. 질문의 사례처럼 10명 중 어린이가 5명이면 청소년 및 어린이 비율이 50% 이상이므로 그 요건을 충족하면 어린이 무료 적용이 가능하다.",
          "b_ids": "도시공원:별표2#행5"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
